css:
.print-heading {
	text-align: right;
	text-transform: uppercase;
	color: #666;
	padding-bottom: 20px;
	margin-bottom: 20px;
	border-bottom: 1px solid #d1d8dd;
}

.print-heading h2 {
	font-size: 24px;
}

.print-format th {
	background-color: #eee !important;
	border-bottom: 0px !important;
}

.print-format .primary.compact-item {
    font-weight: bold;
}

/* modern format: for-test */

.print-format-doc.print-format-doc--standard .section-label {
	font-size: 0.85em;
	font-weight: 600;
	color: var(--gray-600);
	border-bottom: none;
	padding-bottom: 0;
	margin-bottom: 0.75em;
}
.print-format-doc.print-format-doc--standard .print-heading {
	text-align: left;
	text-transform: none;
	color: inherit;
	padding-bottom: 5px;
	margin-bottom: 10px;
}
.print-format-doc.print-format-doc--standard .print-heading h2 {
	font-size: 24px;
}
